intermediate.code:
def withTiming[A](name: String)(op: => A): A = {
  val start = System.nanoTime()
  try op finally println(s"$name took ${System.nanoTime() - start}")
}

final case class User private (name: String)
object User {
  def from(name: String): Option[User] =
    Option(name).filter(_.nonEmpty).map(new User(_))
}

def printValue[A](a: A)(using show: Show[A]): String = show.show(a)
trait Show[A] { def show(a: A): String }
given Show[Int] with { def show(a: Int) = a.toString }

