import scala.annotation.tailrec

@tailrec
def loop(n: Int, acc: Long = 0): Long =
  if (n <= 0) acc else loop(n - 1, acc + n)

@volatile var n = 0

def inc(): Unit = {
  n = n + 1 // visible, but not atomic
}

